package de.dennisguse.opentracks.p0.app;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;
public class DashboardMetricLayoutTest {
 @Test public void defaultsAndEveryExchangePreserveOtherPositions(){for(boolean neon:new boolean[]{false,true}){var base=DashboardMetricLayout.defaults(neon);assertEquals(neon?DashboardMetric.HEART_RATE:DashboardMetric.DISTANCE,base.primary());for(int i=0;i<3;i++){var next=base.swapSecondary(i);assertEquals(base.secondary(i),next.primary());assertEquals(base.primary(),next.secondary(i));for(int j=0;j<3;j++)if(j!=i)assertEquals(base.secondary(j),next.secondary(j));assertEquals(base,next.swapSecondary(i));}}}
 @Test public void allPermutationsRoundTripAndRemainUnique(){var found=new HashSet<DashboardMetricLayout>();var queue=new ArrayDeque<DashboardMetricLayout>();queue.add(DashboardMetricLayout.defaults(false));while(!queue.isEmpty()){var item=queue.remove();if(!found.add(item))continue;assertEquals(item,DashboardMetricLayout.restoreOrDefault(item.serialize(),true));assertEquals(4,new HashSet<>(item.positions()).size());for(int i=0;i<3;i++)queue.add(item.swapSecondary(i));}assertEquals(24,found.size());}
 @Test public void exactOrderedExample(){var start=new DashboardMetricLayout(List.of(DashboardMetric.DURATION,DashboardMetric.DISTANCE,DashboardMetric.PACE_SPEED,DashboardMetric.HEART_RATE));var next=start.swapSecondary(0).swapSecondary(1);assertEquals(List.of(DashboardMetric.PACE_SPEED,DashboardMetric.DURATION,DashboardMetric.DISTANCE,DashboardMetric.HEART_RATE),next.positions());}
 @Test public void corruptionRestoresFamilyDefault(){for(String bad:new String[]{"","DISTANCE","DISTANCE,DURATION,PACE_SPEED,GPS_ACCURACY","DISTANCE,DURATION,PACE_SPEED,DISTANCE","DISTANCE,DURATION,PACE_SPEED,HEART_RATE,","unknown"})for(boolean neon:new boolean[]{false,true})assertEquals(DashboardMetricLayout.defaults(neon),DashboardMetricLayout.restoreOrDefault(bad,neon));assertEquals(DashboardMetricLayout.defaults(true),DashboardMetricLayout.restoreOrDefault(null,true));}
 @Test public void invalidSlotsAndMutationRejected(){var base=DashboardMetricLayout.defaults(false);for(int i:new int[]{-1,3,99}){try{base.swapSecondary(i);fail();}catch(IllegalArgumentException expected){}}var copy=new ArrayList<>(base.positions());var immutable=new DashboardMetricLayout(copy);copy.clear();assertEquals(base,immutable);try{immutable.positions().clear();fail();}catch(UnsupportedOperationException expected){}}
}
